Map<String, String> authorizationCodes = new ConcurrentHashMap<>(); // code -> username
Map<String, String> accessTokens = new ConcurrentHashMap<>(); // token -> username

server.createContext("/authorize", exchange -> {
    // po zalogowaniu i zgodzie uzytkownika:
    String code = UUID.randomUUID().toString();
    authorizationCodes.put(code, "anna");
    redirectTo(exchange, "https://fotodrukarnia.example.com/callback?code=" + code);
});

server.createContext("/token", exchange -> {
    String code = extractParam(exchange, "code");
    String username = authorizationCodes.remove(code); // JEDNORAZOWE uzycie - usuniete od razu
    if (username == null) { respond(exchange, 400, "{\"error\":\"invalid_grant\"}"); return; }
    String accessToken = UUID.randomUUID().toString();
    accessTokens.put(accessToken, username);
    respond(exchange, 200, "{\"access_token\":\"" + accessToken + "\"}");
});

server.createContext("/api/photos", exchange -> {
    String token = extractBearerToken(exchange);
    String username = accessTokens.get(token);
    if (username == null) { exchange.sendResponseHeaders(401, -1); return; }
    respond(exchange, 200, "[{\"photoId\":1,\"owner\":\"" + username + "\"}]");
});

